-- Tests Module 4.9 — Cashflow prévisionnel.
-- Voir docs/briefs/Module-4.9-Cashflow-Previsionnel.md. Chaque scénario
-- s'exécute en BEGIN … ROLLBACK avec des entreprises dédiées : rien ne
-- persiste. Appels en utilisateur authentifié réel (role authenticated + sub),
-- jamais en service_role. Attendus écrits en dur (jsonb : une valeur null doit
-- rester null), recalculés par un modèle de référence indépendant du SQL
-- (script Python écrit à partir des seules règles du brief).

set client_min_messages to notice;

-- ---------------------------------------------------------------------
-- Aides de préparation (exécutées en tant que postgres).
-- Identifiants : 9c + entreprise (2 chiffres) + catégorie (2 hex) + n.
-- ---------------------------------------------------------------------
create function pg_temp.idx(p_ii int, p_cat text, p_n bigint) returns uuid
language sql immutable as $$
  select ('9c' || lpad(p_ii::text, 2, '0') || p_cat || '00-0000-0000-0000-' || lpad(p_n::text, 12, '0'))::uuid;
$$;
grant execute on function pg_temp.idx(int, text, bigint) to authenticated;

create function pg_temp.preparer(p_ii int, p_solde numeric, p_date date) returns void
language plpgsql as $$
begin
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at, confirmation_token, email_change,
    email_change_token_new, recovery_token
  ) values
    ('00000000-0000-0000-0000-000000000000', pg_temp.idx(p_ii, 'c1', 1), 'authenticated', 'authenticated',
     'ceo-9c' || p_ii || '@test.besmart.local', crypt('mot-de-passe-test', gen_salt('bf')),
     now(), '{}', '{}', now(), now(), '', '', '', ''),
    ('00000000-0000-0000-0000-000000000000', pg_temp.idx(p_ii, 'c2', 1), 'authenticated', 'authenticated',
     'comptable-9c' || p_ii || '@test.besmart.local', crypt('mot-de-passe-test', gen_salt('bf')),
     now(), '{}', '{}', now(), now(), '', '', '', '');

  insert into public.entreprises (id, nom, secteur, devise, solde_initial, date_solde_initial)
  values (pg_temp.idx(p_ii, '01', 1), 'Entreprise Cashflow ' || p_ii, 'Test', 'FCFA', p_solde, p_date);

  insert into public.utilisateurs (id, nom, email, role, entreprise_id) values
    (pg_temp.idx(p_ii, 'c1', 1), 'CEO 9c' || p_ii, 'ceo-9c' || p_ii || '@test.besmart.local', 'ceo', pg_temp.idx(p_ii, '01', 1)),
    (pg_temp.idx(p_ii, 'c2', 1), 'Comptable 9c' || p_ii, 'comptable-9c' || p_ii || '@test.besmart.local', 'comptable', pg_temp.idx(p_ii, '01', 1));

  insert into public.categories (id, entreprise_id, libelle, type) values
    (pg_temp.idx(p_ii, '21', 1), pg_temp.idx(p_ii, '01', 1), 'Charges fixes', 'fixe'),
    (pg_temp.idx(p_ii, '22', 1), pg_temp.idx(p_ii, '01', 1), 'Charges variables', 'variable'),
    (pg_temp.idx(p_ii, '23', 1), pg_temp.idx(p_ii, '01', 1), 'Ventes', 'revenu');
end $$;

create function pg_temp.budget(p_ii int, p_an int, p_mo int) returns void
language sql as $$
  insert into public.budgets_mensuels (id, entreprise_id, mois, annee, statut)
  values (pg_temp.idx(p_ii, '40', p_an * 100 + p_mo), pg_temp.idx(p_ii, '01', 1), p_mo, p_an, 'brouillon');
$$;

-- p_type : 'fixe' ou 'variable'.
create function pg_temp.charge(p_ii int, p_an int, p_mo int, p_n int, p_type text, p_designation text, p_montant numeric, p_statut text) returns void
language sql as $$
  insert into public.lignes_charge_prevue (id, budget_mensuel_id, entreprise_id, categorie_id, designation, montant, statut)
  values (pg_temp.idx(p_ii, '50', p_n), pg_temp.idx(p_ii, '40', p_an * 100 + p_mo), pg_temp.idx(p_ii, '01', 1),
          pg_temp.idx(p_ii, case p_type when 'fixe' then '21' else '22' end, 1), p_designation, p_montant, p_statut);
$$;

create function pg_temp.revenu(p_ii int, p_an int, p_mo int, p_n int, p_source text, p_montant numeric, p_statut text) returns void
language sql as $$
  insert into public.lignes_revenu_prevu (id, budget_mensuel_id, entreprise_id, source, montant_estime, statut)
  values (pg_temp.idx(p_ii, '60', p_n), pg_temp.idx(p_ii, '40', p_an * 100 + p_mo), pg_temp.idx(p_ii, '01', 1), p_source, p_montant, p_statut);
$$;

-- p_ligne : numéro de la ligne de revenu liée (null = créance non liée).
create function pg_temp.creance(p_ii int, p_n int, p_client text, p_montant numeric, p_echeance date, p_ligne int) returns void
language sql as $$
  insert into public.creances (id, entreprise_id, client, montant_du, date_facturation, echeance, saisi_par, ligne_revenu_prevu_id)
  values (pg_temp.idx(p_ii, '80', p_n), pg_temp.idx(p_ii, '01', 1), p_client, p_montant, date '2025-11-01', p_echeance,
          pg_temp.idx(p_ii, 'c2', 1), case when p_ligne is null then null else pg_temp.idx(p_ii, '60', p_ligne) end);
$$;

-- p_type : 'entree' ou 'sortie' ; p_creance : numéro de créance payée (ou null).
create function pg_temp.tx(p_ii int, p_date date, p_type text, p_montant numeric, p_creance int default null) returns void
language sql as $$
  insert into public.transactions (entreprise_id, date, description, categorie_id, type, montant, mode_paiement, saisi_par, creance_id)
  values (pg_temp.idx(p_ii, '01', 1), p_date, p_type || ' ' || p_date,
          pg_temp.idx(p_ii, case p_type when 'entree' then '23' else '21' end, 1),
          p_type, p_montant, 'cash', pg_temp.idx(p_ii, 'c1', 1),
          case when p_creance is null then null else pg_temp.idx(p_ii, '80', p_creance) end);
$$;

-- Empreinte des tables que le simulateur ne doit jamais modifier (toutes
-- entreprises confondues : security definer, exécutée sans RLS).
create function pg_temp.empreinte() returns text
language sql security definer set search_path = public as $$
  select md5(
    coalesce((select md5(string_agg(t::text, '|' order by t.id)) from public.transactions t), '') ||
    coalesce((select md5(string_agg(b::text, '|' order by b.id)) from public.budgets_mensuels b), '') ||
    coalesce((select md5(string_agg(l::text, '|' order by l.id)) from public.lignes_charge_prevue l), '') ||
    coalesce((select md5(string_agg(r::text, '|' order by r.id)) from public.lignes_revenu_prevu r), '') ||
    coalesce((select md5(string_agg(c::text, '|' order by c.id)) from public.creances c), '') ||
    coalesce((select md5(string_agg(e::text, '|' order by e.id)) from public.entreprises e), '')
  );
$$;
grant execute on function pg_temp.empreinte() to authenticated;

-- Jeu Cash1 (scénarios 1, 2, 3) : solde 100 000 à la fin du 31/12/2025.
create function pg_temp.jeu_cash1(p_ii int) returns void
language plpgsql as $$
declare m int;
begin
  perform pg_temp.preparer(p_ii, 100000, '2025-12-31');
  -- Février : budget d'un mois passé (sert au refus « ligne d'un mois passé »).
  perform pg_temp.budget(p_ii, 2026, 2);
  perform pg_temp.charge(p_ii, 2026, 2, 21, 'fixe', 'Loyer février', 100000, 'a_faire');
  for m in 3..7 loop
    perform pg_temp.budget(p_ii, 2026, m);
    perform pg_temp.charge(p_ii, 2026, m, m * 10 + 1, 'fixe', 'Loyer', 100000, 'a_faire');
    perform pg_temp.charge(p_ii, 2026, m, m * 10 + 2, 'fixe', 'Salaires', 100000, 'a_faire');
  end loop;
  perform pg_temp.charge(p_ii, 2026, 3, 33, 'variable', 'Matières', 80000, 'a_faire');
  perform pg_temp.charge(p_ii, 2026, 4, 43, 'variable', 'Matières', 100000, 'a_faire');
  perform pg_temp.charge(p_ii, 2026, 4, 44, 'variable', 'Charge annulée', 70000, 'annule');
  perform pg_temp.charge(p_ii, 2026, 5, 53, 'variable', 'Matières', 150000, 'a_faire');
  perform pg_temp.charge(p_ii, 2026, 6, 63, 'variable', 'Achat stock', 900000, 'planifie');
  perform pg_temp.charge(p_ii, 2026, 7, 73, 'variable', 'Matières', 100000, 'a_faire');

  perform pg_temp.revenu(p_ii, 2026, 3, 31, 'Ventes', 300000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 4, 41, 'Ventes', 250000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 4, 42, 'Client Alpha', 200000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 4, 43, 'Vente annulée', 30000, 'annule');
  perform pg_temp.revenu(p_ii, 2026, 5, 51, 'Ventes', 200000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 5, 52, 'Client Beta', 400000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 6, 61, 'Ventes', 100000, 'en_attente');
  perform pg_temp.revenu(p_ii, 2026, 7, 71, 'Ventes', 300000, 'en_attente');

  perform pg_temp.creance(p_ii, 1, 'Alpha', 200000, '2026-04-20', 42);
  perform pg_temp.creance(p_ii, 2, 'Beta', 500000, '2026-05-10', 52);
  perform pg_temp.creance(p_ii, 3, 'Gamma', 150000, '2026-02-28', null);
  perform pg_temp.creance(p_ii, 4, 'Delta', 80000, '2025-12-01', null);
  perform pg_temp.creance(p_ii, 5, 'Epsilon', 60000, '2026-01-20', null);
  perform pg_temp.creance(p_ii, 6, 'Zeta', 40000, '2026-04-05', null);

  perform pg_temp.tx(p_ii, '2026-01-10', 'entree', 340000);
  perform pg_temp.tx(p_ii, '2026-01-15', 'sortie', 250000);
  perform pg_temp.tx(p_ii, '2026-01-28', 'entree', 60000, 5);
  perform pg_temp.tx(p_ii, '2026-02-12', 'entree', 100000, 2);
  perform pg_temp.tx(p_ii, '2026-02-20', 'entree', 200000);
  perform pg_temp.tx(p_ii, '2026-02-25', 'sortie', 280000);
  perform pg_temp.tx(p_ii, '2026-03-05', 'entree', 120000);
  perform pg_temp.tx(p_ii, '2026-03-08', 'sortie', 90000);
  perform pg_temp.tx(p_ii, '2026-03-15', 'entree', 50000, 3);
end $$;

-- Comparaison jsonb complète, lignes triées comme la fonction (mois puis trimestres).
create function pg_temp.obtenu(p_ref date, p_rep jsonb default '[]', p_ret jsonb default '[]') returns jsonb
language sql as $$
  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
  from public.cashflow_previsionnel(p_ref, p_rep, p_ret) x;
$$;
grant execute on function pg_temp.obtenu(date, jsonb, jsonb) to authenticated;

create function pg_temp.verifier(p_nom text, p_obtenu jsonb, p_attendu jsonb) returns void
language plpgsql as $$
declare i int;
begin
  if p_obtenu is distinct from p_attendu then
    for i in 0 .. greatest(jsonb_array_length(p_obtenu), jsonb_array_length(p_attendu)) - 1 loop
      if p_obtenu -> i is distinct from p_attendu -> i then
        raise exception '% : ligne % différente. obtenu = % ; attendu = %', p_nom, i, p_obtenu -> i, p_attendu -> i;
      end if;
    end loop;
  end if;
end $$;
grant execute on function pg_temp.verifier(text, jsonb, jsonb) to authenticated;

-- Message d'une simulation refusée (ou 'ACCEPTEE' si aucune exception).
create function pg_temp.refus(p_ref date, p_rep jsonb, p_ret jsonb) returns text
language plpgsql as $$
begin
  perform count(*) from public.cashflow_previsionnel(p_ref, p_rep, p_ret);
  return 'ACCEPTEE';
exception when others then
  return sqlerrm;
end $$;
grant execute on function pg_temp.refus(date, jsonb, jsonb) to authenticated;

-- ---------------------------------------------------------------------
-- 0. Propriétés de sécurité de la fonction (adversarial 5).
-- ---------------------------------------------------------------------
begin;

do $$
declare
  v_def boolean;
  v_config text[];
  v_grantees text[];
  v_corps text;
  v_nom text := 'public.cashflow_previsionnel(date, jsonb, jsonb)';
begin
  select prosecdef, proconfig into v_def, v_config from pg_proc where oid = v_nom::regprocedure;
  if v_def then raise exception '% ne doit jamais être security definer', v_nom; end if;
  if not ('search_path=public' = any (coalesce(v_config, '{}'))) then
    raise exception '% doit fixer search_path = public (config : %)', v_nom, v_config;
  end if;
  if (select provolatile from pg_proc where oid = v_nom::regprocedure) <> 's' then
    raise exception '% doit être stable (PostgreSQL y interdit toute écriture)', v_nom;
  end if;

  select array_agg(g order by g) into v_grantees
  from (
    select distinct case a.grantee when 0 then 'PUBLIC' else pg_get_userbyid(a.grantee)::text end as g
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
    where p.oid = v_nom::regprocedure and a.privilege_type = 'EXECUTE'
  ) q;
  if v_grantees is distinct from array['authenticated', 'postgres', 'service_role'] then
    raise exception 'ACL de % : droits EXECUTE = % (attendu : authenticated, postgres, service_role, jamais PUBLIC ni anon)', v_nom, v_grantees;
  end if;
  if has_function_privilege('anon', v_nom::regprocedure, 'execute') then raise exception 'ACL : anon peut exécuter %', v_nom; end if;
  if not has_function_privilege('authenticated', v_nom::regprocedure, 'execute') then raise exception 'ACL : authenticated ne peut pas exécuter %', v_nom; end if;

  -- Leçon du 4.8 : la restriction au CEO existe à plusieurs niveaux
  -- (solde_caisse_a, creances_situation, RLS). Le retrait de la seule
  -- restriction de cashflow_previsionnel ne ferait donc échouer aucun test de
  -- comportement : seule la lecture du corps le garantit.
  v_corps := pg_get_functiondef(v_nom::regprocedure);
  if v_corps !~ 'current_role_utilisateur\(\)\s*=\s*''ceo''' then
    raise exception '% doit se restreindre elle-même au CEO (current_role_utilisateur() = ''ceo'')', v_nom;
  end if;
  -- Le corps n'écrit jamais (aucune instruction d'écriture, aucun perform).
  if v_corps ~* '\m(insert\s+into|update\s+public|delete\s+from|perform)\M' then
    raise exception '% : le corps contient une instruction d''écriture ou un perform', v_nom;
  end if;

  if not exists (select 1 from pg_class where relname = 'transactions_date_idx')
     or not exists (select 1 from pg_class where relname = 'creances_entreprise_echeance_idx') then
    raise exception 'index transactions_date_idx ou creances_entreprise_echeance_idx introuvable';
  end if;

  raise notice 'OK — cashflow_previsionnel : security invoker, stable, search_path fixé, ACL sans PUBLIC ni anon, authenticated autorisé, restriction au CEO dans le corps, aucune écriture ; index existants présents';
end $$;

rollback;

