end $$;

-- Cohérences : identités, continuité, sommes des mois = trimestres, recoupements.
do $$
declare
  r record;
  v_prec numeric;
  v_nb int := 0;
begin
  for r in select * from public.cashflow_previsionnel('2026-03-15') where granularite = 'mois' and projete order by annee, periode loop
    if r.solde_fin <> r.solde_debut + r.resultat or r.resultat <> r.encaissements - r.depenses
       or r.encaissements <> r.encaissements_budget + r.encaissements_creances then
      raise exception 'IDENTITE rompue au mois %-%', r.annee, r.periode;
    end if;
    if v_prec is not null and r.solde_debut <> v_prec then
      raise exception 'CONTINUITE rompue au mois %-% (début % ≠ fin précédente %)', r.annee, r.periode, r.solde_debut, v_prec;
    end if;
    v_prec := r.solde_fin;
    v_nb := v_nb + 1;
  end loop;
  if v_nb <> 5 then raise exception 'COHERENCE : 5 mois projetés attendus, % obtenus', v_nb; end if;

  if (select sum(depenses) from public.cashflow_previsionnel('2026-03-15') where granularite = 'mois')
     <> (select sum(depenses) from public.cashflow_previsionnel('2026-03-15') where granularite = 'trimestre') then
    raise exception 'SOMMES : les dépenses des mois et des trimestres diffèrent';
  end if;

  -- Point de départ = solde_caisse_a(date de référence), pas la fin de février.
  if (select solde_debut from public.cashflow_previsionnel('2026-03-15') where granularite = 'mois' and annee = 2026 and periode = 3)
     <> public.solde_caisse_a('2026-03-15') or public.solde_caisse_a('2026-03-15') <> 350000
     or public.solde_caisse_a('2026-02-28') <> 270000 then
    raise exception 'DEPART : le solde de départ doit être solde_caisse_a(2026-03-15) = 350 000 (fin février = 270 000)';
  end if;

  -- Recoupement avec le 4.6 : réel de mars à la date de référence (aucune
  -- transaction postérieure) : sorties 90 000, entrées 170 000.
  if (select depenses_reel from public.ecarts_mensuels(2026, '2026-03-15') where mois = 3) <> 90000
     or (select revenus_reel from public.ecarts_mensuels(2026, '2026-03-15') where mois = 3) <> 170000 then
    raise exception 'RECOUPEMENT 4.6 : le réel de mars à date diffère (attendu 170 000 / 90 000)';
  end if;

  -- Jamais d'encaissement de créance sur un mois non projeté.
  if exists (select 1 from public.cashflow_previsionnel('2026-03-15') where not projete and encaissements_creances is not null) then
    raise exception 'Un mois non projeté porte un encaissement de créance';
  end if;

  -- Simulation vide = base, champ par champ.
  if exists (
    select 1 from public.cashflow_previsionnel('2026-03-15', '[]', '[]') x
    where x.projete and (x.encaissements_simule <> x.encaissements or x.depenses_simule <> x.depenses
      or x.solde_fin_simule <> x.solde_fin or x.ecart_solde_fin <> 0 or x.solde_negatif_simule <> x.solde_negatif)
  ) then
    raise exception 'SIMULATION VIDE : les colonnes simulées doivent égaler la base';
  end if;

  raise notice 'OK — scénario 1 : identités, continuité (4 paires), sommes mois = trimestres, départ = solde_caisse_a(2026-03-15) = 350 000 ≠ fin février 270 000, réel de mars = ecarts_mensuels (170 000 / 90 000), simulation vide = base';
end $$;

rollback;

-- ---------------------------------------------------------------------
-- 2. Scénario 2 — simulations sur Cash1, et étanchéité du simulateur
--    (adversarial 6) : empreintes avant/après chaque simulation, réussies et
--    refusées.
-- ---------------------------------------------------------------------
begin;

select pg_temp.jeu_cash1(1);
create temp table empreintes (etape text, valeur text);
insert into empreintes values ('avant', pg_temp.empreinte());
grant select, insert on empreintes to authenticated;

set local role authenticated;
set local request.jwt.claims = '{"sub": "9c01c100-0000-0000-0000-000000000001", "role": "authenticated"}';

