-- ---------------------------------------------------------------------
-- 3. Scénario 3 — simulations refusées (toujours dans la transaction du
--    scénario 2). Une entreprise voisine (Cash9) fournit les identifiants
--    « d'une autre entreprise ».
-- ---------------------------------------------------------------------
reset role;
select pg_temp.preparer(9, 0, '2025-12-31');
select pg_temp.budget(9, 2026, 6);
select pg_temp.charge(9, 2026, 6, 61, 'fixe', 'Loyer Cash9', 100000, 'a_faire');
select pg_temp.creance(9, 1, 'Client Cash9', 10000, '2026-06-30', null);
insert into empreintes values ('avant_s3', pg_temp.empreinte());
set local role authenticated;
set local request.jwt.claims = '{"sub": "9c01c100-0000-0000-0000-000000000001", "role": "authenticated"}';

do $$
declare
  v_cas record;
  v_msg text;
  v_avant text;
  v_stock text := pg_temp.idx(1, '50', 63)::text;
  v_mat7 text := pg_temp.idx(1, '50', 73)::text;
  v_ann4 text := pg_temp.idx(1, '50', 44)::text;
  v_fev text := pg_temp.idx(1, '50', 21)::text;
  v_autre_ligne text := pg_temp.idx(9, '50', 61)::text;
  v_autre_creance text := pg_temp.idx(9, '80', 1)::text;
  v_inconnu text := '9c990000-0000-0000-0000-000000000000';
  v_msg_ligne_autre text;
  v_msg_ligne_inconnue text;
  v_msg_creance_autre text;
  v_msg_creance_inconnue text;
  r jsonb;
begin
  for v_cas in
    select * from (values
      ('retarder Delta (plus_60)', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 4)::text, 'jours', 10)), 'n''est pas attendue'),
      ('retarder Epsilon (soldée)', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 5)::text, 'jours', 10)), 'n''est pas attendue'),
      ('reporter Charge annulée', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_ann4, 'montant', 10000, 'vers_annee', 2026, 'vers_mois', 5)), '[]'::jsonb, 'annulée ou réalisée'),
      ('reporter 900 001 d''Achat stock', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 900001, 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'dépasse le montant de la ligne'),
      ('deux reports dépassant la ligne', jsonb_build_array(
          jsonb_build_object('ligne_charge_id', v_stock, 'montant', 500000, 'vers_annee', 2026, 'vers_mois', 7),
          jsonb_build_object('ligne_charge_id', v_stock, 'montant', 400001, 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'dépasse le montant de la ligne'),
      ('reporter vers août (non projeté)', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 8)), '[]'::jsonb, 'n''est pas un mois projeté'),
      ('reporter vers le même mois', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 6)), '[]'::jsonb, 'mois d''origine'),
      ('avancer une dépense (juillet vers juin)', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_mat7, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 6)), '[]'::jsonb, 'mois postérieur'),
      ('reporter une ligne d''un mois passé', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_fev, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 4)), '[]'::jsonb, 'mois passé'),
      ('jours = 0', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', 0)), 'au moins un jour'),
      ('jours < 0', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', -5)), 'au moins un jour'),
      ('jours non entier', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', 1.5)), 'retard attendu'),
      ('même créance retardée deux fois', '[]'::jsonb, jsonb_build_array(
          jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', 5),
          jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', 6)), 'qu''une fois'),
      ('montant = 0', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 0, 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'doit être positif'),
      ('montant < 0', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', -1, 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'doit être positif'),
      ('JSON : objet au lieu d''une liste', '{"ligne_charge_id": "x"}'::jsonb, '[]'::jsonb, 'doivent être une liste'),
      ('JSON : liste de retards non liste', '[]'::jsonb, '"abc"'::jsonb, 'doivent être une liste'),
      ('JSON : clé manquante', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 1000)), '[]'::jsonb, 'report attendu'),
      ('JSON : montant en texte', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', '1000', 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'report attendu'),
      ('JSON : uuid invalide', jsonb_build_array(jsonb_build_object('ligne_charge_id', 'pas-un-uuid', 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 7)), '[]'::jsonb, 'report attendu'),
      ('JSON : mois 13', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_stock, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 13)), '[]'::jsonb, 'report attendu'),
      ('JSON : élément non objet', '[42]'::jsonb, '[]'::jsonb, 'report attendu'),
      ('JSON : retard sans jours', '[]'::jsonb, jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text)), 'retard attendu')
    ) as t(nom, rep, ret, attendu)
  loop
    v_avant := pg_temp.empreinte();
    v_msg := pg_temp.refus('2026-03-15', v_cas.rep, v_cas.ret);
    if v_msg = 'ACCEPTEE' or position(v_cas.attendu in v_msg) = 0 then
      raise exception 'SCENARIO 3 « % » : attendu un refus contenant « % », obtenu « % »', v_cas.nom, v_cas.attendu, v_msg;
    end if;
    if pg_temp.empreinte() <> v_avant then
      raise exception 'ETANCHEITE : la simulation refusée « % » a modifié les données', v_cas.nom;
    end if;
    raise notice 'S3 % : refusé — "%"', v_cas.nom, v_msg;
  end loop;

  -- Identifiants d'une autre entreprise : même message qu'un identifiant inexistant.
  v_msg_ligne_autre := pg_temp.refus('2026-03-15', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_autre_ligne, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 7)), '[]');
  v_msg_ligne_inconnue := pg_temp.refus('2026-03-15', jsonb_build_array(jsonb_build_object('ligne_charge_id', v_inconnu, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 7)), '[]');
  v_msg_creance_autre := pg_temp.refus('2026-03-15', '[]', jsonb_build_array(jsonb_build_object('creance_id', v_autre_creance, 'jours', 5)));
  v_msg_creance_inconnue := pg_temp.refus('2026-03-15', '[]', jsonb_build_array(jsonb_build_object('creance_id', v_inconnu, 'jours', 5)));
  if v_msg_ligne_autre = 'ACCEPTEE' or v_msg_ligne_autre <> v_msg_ligne_inconnue then
    raise exception 'ISOLATION : ligne d''une autre entreprise « % » ≠ ligne inexistante « % »', v_msg_ligne_autre, v_msg_ligne_inconnue;
  end if;
  if v_msg_creance_autre = 'ACCEPTEE' or v_msg_creance_autre <> v_msg_creance_inconnue then
    raise exception 'ISOLATION : créance d''une autre entreprise « % » ≠ créance inexistante « % »', v_msg_creance_autre, v_msg_creance_inconnue;
  end if;
  raise notice 'S3 ligne de charge d''une autre entreprise / inexistante : même message — "%"', v_msg_ligne_autre;
  raise notice 'S3 créance d''une autre entreprise / inexistante : même message — "%"', v_msg_creance_autre;

  insert into empreintes values ('apres_s3', pg_temp.empreinte());
  raise notice 'OK — scénario 3 : 23 simulations invalides refusées par une exception explicite, identifiants d''une autre entreprise indiscernables d''identifiants inexistants, empreinte identique après chaque refus';
end $$;

-- Étanchéité, suite : empreintes globales, puis exécution en transaction READ ONLY.
reset role;
do $$
begin
  if (select valeur from empreintes where etape = 'avant') <> (select valeur from empreintes where etape = 'apres_s2')
     or (select valeur from empreintes where etape = 'avant_s3') <> (select valeur from empreintes where etape = 'apres_s3') then
    raise exception 'ETANCHEITE : empreinte globale modifiée par les simulations';
  end if;
end $$;

set transaction read only;
set local role authenticated;
set local request.jwt.claims = '{"sub": "9c01c100-0000-0000-0000-000000000001", "role": "authenticated"}';
do $$
declare v_nb int;
begin
  -- Témoin : la transaction est bien en lecture seule.
  begin
    insert into public.categories (entreprise_id, libelle, type) values (pg_temp.idx(1, '01', 1), 'Témoin', 'fixe');
    raise exception 'TEMOIN : la transaction devrait être en lecture seule';
  exception when read_only_sql_transaction then
    null;
  end;
  select count(*) into v_nb from public.cashflow_previsionnel('2026-03-15',
    jsonb_build_array(jsonb_build_object('ligne_charge_id', pg_temp.idx(1, '50', 63)::text, 'montant', 900000, 'vers_annee', 2026, 'vers_mois', 7)),
    jsonb_build_array(jsonb_build_object('creance_id', pg_temp.idx(1, '80', 2)::text, 'jours', 45)));
  if v_nb <> 17 then raise exception 'READ ONLY : 17 lignes attendues, % obtenues', v_nb; end if;
  raise notice 'OK — étanchéité : empreintes globales identiques avant/après les scénarios 2 et 3 ; simulation S2d exécutée sans erreur dans une transaction READ ONLY (témoin d''écriture refusé)';
end $$;

rollback;

