-- 4. Scénario 4 — mois en cours sans budget (Cash2), entreprise vide (Cash3).
-- ---------------------------------------------------------------------
begin;

select pg_temp.preparer(2, 250000, '2025-12-31');
select pg_temp.budget(2, 2026, 4);
select pg_temp.budget(2, 2026, 5);
select pg_temp.revenu(2, 2026, 4, 41, 'Ventes', 100000, 'en_attente');
select pg_temp.charge(2, 2026, 4, 41, 'fixe', 'Loyer', 50000, 'a_faire');
select pg_temp.revenu(2, 2026, 5, 51, 'Ventes', 100000, 'en_attente');
select pg_temp.charge(2, 2026, 5, 51, 'fixe', 'Loyer', 50000, 'a_faire');
select pg_temp.preparer(3, 0, '2025-12-31');

set local role authenticated;
set local request.jwt.claims = '{"sub": "9c02c100-0000-0000-0000-000000000001", "role": "authenticated"}';
