-- ---------------------------------------------------------------------
-- 8. Adversariaux 1 à 4 : comptable, supervision, isolation A/B, anon.
-- ---------------------------------------------------------------------
begin;

select pg_temp.jeu_cash1(1);
select pg_temp.preparer(7, 999000, '2025-12-31');
select pg_temp.budget(7, 2026, 3);
select pg_temp.revenu(7, 2026, 3, 31, 'Ventes B', 10000, 'en_attente');
select pg_temp.charge(7, 2026, 3, 31, 'fixe', 'Loyer B', 5000, 'a_faire');
select pg_temp.creance(7, 1, 'Client B', 7000, '2026-03-31', null);

set local role authenticated;

-- 1. Comptable de Cash1 : zéro ligne, même avec une simulation invalide, sans erreur.
set local request.jwt.claims = '{"sub": "9c01c200-0000-0000-0000-000000000001", "role": "authenticated"}';
do $$
declare v_nb int;
begin
  if not exists (select 1 from public.creances) or not exists (select 1 from public.v_budget_mensuel_totaux) then
    raise exception 'ADV1 : le comptable devrait lire les créances et le budget (sinon le test ne prouve rien)';
  end if;
  select count(*) into v_nb from public.cashflow_previsionnel('2026-03-15');
  if v_nb <> 0 then raise exception 'ADV1 : le comptable obtient % lignes (attendu 0)', v_nb; end if;
  select count(*) into v_nb from public.cashflow_previsionnel('2026-03-15', '{"pas": "une liste"}', '[42]');
  if v_nb <> 0 then raise exception 'ADV1 : le comptable obtient % lignes avec une simulation invalide', v_nb; end if;
  raise notice 'OK — adversarial 1 : le comptable obtient zéro ligne, sans erreur, même avec des paramètres de simulation invalides';
end $$;

-- 2. Supervision Be Smart : zéro ligne.
set local request.jwt.claims = '{"sub": "c0000000-0000-0000-0000-000000000001", "role": "authenticated", "app_metadata": {"super_admin": true}}';
do $$
declare v_nb int;
begin
  select count(*) into v_nb from public.cashflow_previsionnel('2026-03-15', '"invalide"', '"invalide"');
  if v_nb <> 0 then raise exception 'ADV2 : la supervision obtient % lignes (attendu 0)', v_nb; end if;
  raise notice 'OK — adversarial 2 : la supervision Be Smart obtient zéro ligne, sans erreur';
end $$;

-- 3. Isolation A / B : chaque CEO ne voit que ses propres chiffres.
set local request.jwt.claims = '{"sub": "9c07c100-0000-0000-0000-000000000001", "role": "authenticated"}';
do $$
declare r record;
begin
  select * into r from public.cashflow_previsionnel('2026-03-15') where granularite = 'mois' and annee = 2026 and periode = 3;
  -- Cash7 : départ 999 000, budget 10 000 de ventes, 5 000 de charges, créance de 7 000.
  if r.solde_debut <> 999000 or r.encaissements_budget <> 10000 or r.encaissements_creances <> 7000 or r.depenses <> 5000 then
    raise exception 'ADV3 : CEO de Cash7 voit d''autres chiffres que les siens : %', to_jsonb(r);
  end if;
  if (select count(*) from public.cashflow_previsionnel('2026-03-15') where projete) <> 2 then
    raise exception 'ADV3 : CEO de Cash7 devrait avoir 1 mois et 1 trimestre projetés';
  end if;
  if pg_temp.refus('2026-03-15', jsonb_build_array(jsonb_build_object('ligne_charge_id', pg_temp.idx(1, '50', 63)::text, 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 3)), '[]')
     <> pg_temp.refus('2026-03-15', jsonb_build_array(jsonb_build_object('ligne_charge_id', '9c990000-0000-0000-0000-000000000000', 'montant', 1000, 'vers_annee', 2026, 'vers_mois', 3)), '[]') then
    raise exception 'ADV3 : viser une ligne de Cash1 depuis Cash7 doit donner le même message qu''un id inexistant';
  end if;
  raise notice 'OK — adversarial 3 : le CEO de B ne voit que ses chiffres (999 000, 10 000, 7 000, 5 000) ; viser une ligne de A donne le même message qu''un id inexistant';
end $$;

set local request.jwt.claims = '{"sub": "9c01c100-0000-0000-0000-000000000001", "role": "authenticated"}';
do $$
begin
  if (select solde_debut from public.cashflow_previsionnel('2026-03-15') where granularite = 'mois' and annee = 2026 and periode = 3) <> 350000 then
    raise exception 'ADV3 : le CEO de Cash1 voit d''autres chiffres que les siens';
  end if;
  raise notice 'OK — adversarial 3 : le CEO de A ne voit que ses chiffres (350 000)';
end $$;

-- 4. anon : permission refusée.
set local role anon;
do $$
begin
  begin
    perform count(*) from public.cashflow_previsionnel('2026-03-15');
    raise exception 'ADV4 : anon a pu exécuter cashflow_previsionnel';
  exception when insufficient_privilege then
    raise notice 'OK — adversarial 4 : anon — permission refusée sur cashflow_previsionnel';
  end;
end $$;

rollback;
